use std::fs;
use std::collections::{HashMap, HashSet};

// Embed the C runtime source so the compiler can compile it on-the-fly.
const RUNTIME_C_SOURCE: &str = include_str!("codegen/runtime/runtime.c");
const RUNTIME_H_SOURCE: &str = include_str!("codegen/runtime/runtime.h");
use std::sync::{Mutex, OnceLock};
use std::hash::{Hash, Hasher};

// ===== String Interning (Phase 1) =====
// Identifiers/type names are interned into a stable `u32` id so that name
// resolution and type comparison avoid repeated `String` hashing and allocation.
// A single global interner is used; lookups are O(1) amortized and lock
// contention is negligible for compiler front-end workloads (each call interns
// at most once per distinct name).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct Symbol(u32);

impl Symbol {
    const AMBIGUOUS: Symbol = Symbol(u32::MAX);
}

struct Interner {
    map: HashMap<String, Symbol>,
    values: Vec<String>,
}

impl Interner {
    fn new() -> Self {
        Interner {
            map: HashMap::new(),
            values: Vec::new(),
        }
    }

    fn intern(&mut self, name: &str) -> Symbol {
        if let Some(s) = self.map.get(name) {
            return *s;
        }
        let id = self.values.len() as u32;
        let sym = Symbol(id);
        self.values.push(name.to_string());
        self.map.insert(name.to_string(), sym);
        sym
    }

    fn resolve(&self, symbol: Symbol) -> &str {
        &self.values[symbol.0 as usize]
    }
}

fn global_interner() -> &'static Mutex<Interner> {
    static INTERNER: OnceLock<Mutex<Interner>> = OnceLock::new();
    INTERNER.get_or_init(|| Mutex::new(Interner::new()))
}

/// Intern a name, returning its stable `Symbol`.
fn intern(name: &str) -> Symbol {
    let mut i = global_interner().lock().unwrap();
    i.intern(name)
}

/// Lightweight stage profiler. Active only when `LIME_PROFILE` is set in the
/// environment; otherwise every call is a no-op with zero runtime cost (the
/// timer is constructed inline and dropped immediately without locking).
struct StageTimer {
    name: &'static str,
    start: std::time::Instant,
}
impl StageTimer {
    fn new(name: &'static str) -> Self {
        let _ = std::env::var("LIME_PROFILE");
        StageTimer {
            name,
            start: std::time::Instant::now(),
        }
    }
}
impl Drop for StageTimer {
    fn drop(&mut self) {
        if std::env::var("LIME_PROFILE").is_ok() {
            let d = self.start.elapsed();
            let micros = d.as_micros();
            eprintln!("[profile] {}: {} us", self.name, micros);
        }
    }
}

/// Resolve a `Symbol` back to its string (panics only on a corrupt id).
fn resolve_sym(symbol: Symbol) -> String {
    let i = global_interner().lock().unwrap();
    i.resolve(symbol).to_string()
}

// Phase 2: memoization cache for `type_from_str`. Type strings are parsed
// repeatedly during type-checking and monomorphization (every `type_hint`,
// parameter type, `type_from_str` call site); caching the parsed `Type` avoids
// re-running the recursive `split(',')` / suffix-scan parsing on each use.
// Resolution is deterministic per `Defs`, and `Defs` is immutable for the
// duration of a single compilation, so keying solely by the input string is
// sound within one compile.
fn global_type_cache() -> &'static Mutex<HashMap<String, Type>> {
    static CACHE: OnceLock<Mutex<HashMap<String, Type>>> = OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(HashMap::new()))
}

// Phase 2: package definition cache. A resolved package (`<pkg>/v<ver>/citrus.toml`)
// never changes between compiles within a process, yet `apply_to_defs` previously
// re-tokenized, re-parsed and re-indexed every imported package on every compile.
// Caching the merged+indexed `Defs` per package path collapses that work to a
// clone after the first compile (the interned indexes remain valid process-wide).
fn global_pkg_cache() -> &'static Mutex<HashMap<String, Defs>> {
    static CACHE: OnceLock<Mutex<HashMap<String, Defs>>> = OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(HashMap::new()))
}

// Phase 1: monomorphization cache key. Identifies a generic instantiation by
// the (interned) function symbol and its concrete type arguments, so the same
// instantiation is never monomorphized twice. `mangled` is carried as metadata
// for external references (defs insertion / call updates) but is excluded from
// the hash/eq so the key is canonical over (function, types).
#[derive(Clone)]
struct MonoKey {
    function: Symbol,
    types: Vec<String>,
    mangled: String,
}

impl PartialEq for MonoKey {
    fn eq(&self, other: &Self) -> bool {
        self.function == other.function && self.types == other.types
    }
}

impl Eq for MonoKey {}

impl Hash for MonoKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.function.hash(state);
        self.types.hash(state);
    }
}

