fn type_to_string(ty: &Type) -> String {
    match ty {
        Type::Int => "int".to_string(),
        Type::Float => "float".to_string(),
        Type::Bool => "bool".to_string(),
        Type::String => "str".to_string(),
        Type::Struct(name) => name.clone(),
        Type::State(name) => name.clone(),
        Type::List(inner) => format!("List({})", type_to_string(inner)),
        Type::Option(inner) => format!("Option({})", type_to_string(inner)),
        Type::Interface(name, args) => {
            let args_str: Vec<String> = args.iter().map(type_to_string).collect();
            format!("{}({})", name, args_str.join(", "))
        }
        Type::Var(name) => name.clone(),
        Type::Long => "long".to_string(),
        Type::Unit => "void".to_string(),
        Type::Unknown => "unknown".to_string(),
        Type::Array(inner) => format!("Array({})", type_to_string(inner)),
        Type::Slice(inner) => format!("Slice({})", type_to_string(inner)),
        Type::Tuple(elems) => {
            let strs: Vec<String> = elems.iter().map(type_to_string).collect();
            format!("({})", strs.join(", "))
        }
        Type::Fn(params, ret) => {
            let param_strs: Vec<String> = params.iter().map(type_to_string).collect();
            format!("fn({}) -> {}", param_strs.join(", "), type_to_string(ret))
        }
        Type::Json => "json".to_string(),
    }
}

/// Build a rich "type mismatch" message showing the expected and received types
/// on separate indented lines (Phase 8 Step 1). The one-line summary stays the
/// first line so existing substring assertions (`binary '+' type mismatch`,
/// `tuple pattern size mismatch`, ...) keep matching.
fn type_mismatch_msg(summary: &str, expected: &Type, received: &Type) -> String {
    format!(
        "Type error: {}\n\nexpected:\n    {}\n\nreceived:\n    {}",
        summary,
        type_to_string(expected),
        type_to_string(received)
    )
}

/// Build a function signature string for error messages.
/// e.g. `fn add(int: a, int: b) -> int`
fn fn_signature(name: &str, params: &[(String, String)], return_type: &Option<String>) -> String {
    let param_strs: Vec<String> = params
        .iter()
        .map(|(n, t)| format!("{}: {}", n, t))
        .collect();
    let ret_str = match return_type {
        Some(rt) => format!(" -> {}", rt),
        None => String::new(),
    };
    format!("fn {}({}){}", name, param_strs.join(", "), ret_str)
}

fn type_eq(a: &Type, b: &Type) -> bool {
    match (a, b) {
        (Type::Unknown, _) | (_, Type::Unknown) => true,
        (Type::Option(inner_a), Type::Option(inner_b)) => type_eq(inner_a, inner_b),
        (Type::List(inner_a), Type::List(inner_b)) => type_eq(inner_a, inner_b),
        (Type::Array(inner_a), Type::Array(inner_b)) => type_eq(inner_a, inner_b),
        // Generic 鬮ｯ諛ｷ髮驍・・・ｭ・ｫ陞滄托ｽｰ蟷・ｽｫ・､隲幢ｽｶ繝ｻ・ｿ繝ｻ・ｽE Var 鬩搾ｽｵ繝ｻ・ｺ郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽ Unknown 鬩幢ｽ｢繝ｻ・ｧ髯橸ｽｳ陞滂ｽｲ繝ｻ・ｽ繝ｻ・ｿ髫ｴ竏ｵ閻ｸ繝ｻ・ｼ繝ｻ・ｰ鬩搾ｽｵ繝ｻ・ｲ驕ｶ荵怜款繝ｻ・ｽ繝ｻ・ｽ郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽ鬩搾ｽｵ繝ｻ・ｺ郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽ鬩搾ｽｵ繝ｻ・ｺ郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽ鬩搾ｽｵ繝ｻ・ｺ郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽ鬩搾ｽｵ繝ｻ・ｺ驛｢譎｢・ｽ・ｻ
        (Type::Var(_), _) | (_, Type::Var(_)) => true,
        // Two struct/state types with the same base name are compatible even if
        // their generic arguments differ textually (e.g. `HashMap(K,V)` vs
        // `HashMap(int,int)`); the concrete args are supplied by the call site.
        (Type::Struct(a), Type::Struct(b)) => struct_base_eq(a, b),
        (Type::State(a), Type::State(b)) => struct_base_eq(a, b),
        (Type::Option(inner), Type::State(name)) | (Type::State(name), Type::Option(inner)) => {
            // An `Option(T)` parameter (or `Some(x)` constructor producing a
            // `State("Option(int)")`) must match any `Option<...>` state.
            // When the Option side still carries a type variable (e.g. the
            // un-substituted `T` of a generic helper) it is a wildcard.
            if matches!(inner.as_ref(), Type::Var(_) | Type::Unknown) {
                struct_base(name) == "Option"
            } else {
                struct_base(name) == "Option"
                    && format!("Option({})", type_to_string(inner)) == *name
            }
        }
        _ => a == b,
    }
}

/// Base name of a (possibly generic) struct/state type string, stripping any
/// `(...)` type arguments, so `HashMap(int,int)` and `HashMap(K,V)` share
/// the same base `HashMap`.
fn struct_base(name: &str) -> String {
    match name.find('(') {
        Some(i) => name[..i].to_string(),
        None => name.to_string(),
    }
}

/// Allocation-free variant of `struct_base` equality: compares the base-name
/// prefix (up to the first `(`, or the whole string) of two type-name strings
/// without building intermediate `String`s. Used hot in `type_eq`.
fn struct_base_eq(a: &str, b: &str) -> bool {
    let ab = match a.find('(') {
        Some(i) => &a[..i],
        None => a,
    };
    let bb = match b.find('(') {
        Some(i) => &b[..i],
        None => b,
    };
    ab == bb
}

/// The generic argument substrings inside a `(...)` suffix of a type name.
/// `HashMap(int,int)` -> `["int", "int"]`; `HashMap` -> `[]`.
fn generic_args_of(name: &str) -> Vec<String> {
    let inner = match name.find('(') {
        Some(i) => &name[i + 1..],
        None => return Vec::new(),
    };
    let inner = inner.strip_suffix(')').unwrap_or(inner);
    if inner.trim().is_empty() {
        return Vec::new();
    }
    inner.split(',').map(|a| a.trim().to_string()).collect()
}

