fn struct_satisfies_interface(defs: &Defs, sname: &str, iface_name: &str) -> bool {
    let sdef = match defs.structs.get(sname) {
        Some(s) => s,
        None => return false,
    };
    let iface = match defs.interfaces.get(iface_name) {
        Some(i) => i,
        None => return false,
    };
    for im in &iface.methods {
        match sdef.methods.get(&im.name) {
            Some(mdef) if method_sig_matches(defs, mdef, im) => {}
            _ => return false,
        }
    }
    true
}

// 鬮ｯ諛ｷ髮驍・・・ｭ・ｫ陞滄托ｽｰ蟷・ｽｫ・､隲幢ｽｶ繝ｻ・ｿ繝ｻ・ｽE鬮｣蛹・ｽｽ・ｳ郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽ鬩搾ｽｵ繝ｻ・ｺ郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽ鬮ｯ諛ｷ蟋薙・・ｹ隴擾ｽｴ・趣ｽ､鬩幢ｽ｢隴趣ｽ｢繝ｻ・ｽ繝ｻ・ｩ鬩幢ｽ｢隴趣ｽ｢繝ｻ・ｽ繝ｻ・｡鬩幢ｽ｢隴趣ｽ｢繝ｻ・ｽ繝ｻ・ｼ鬩幢ｽ｢繝ｻ・ｧ郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽ鬩幢ｽ｢繝ｻ・ｧ驛｢譎｢・ｽ・ｻarg 鬩搾ｽｵ繝ｻ・ｺ郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽ鬯ｩ蜉ｱ・代・・ｽ繝ｻ・ｮ鬮ｫ・ｰ繝ｻ・ｰ髯晢ｽｷ繝ｻ・｢郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽ驛｢譎｢・ｽ・ｻeneric Operator Interface 鬩搾ｽｵ繝ｻ・ｺ郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽE郢晢ｽｻ繝ｻ・ｽ鬮ｯ讖ｸ・ｽ・ｳ髮玖ｴ具ｽｼ螟ｲ・ｽ・ｽ繝ｻ・ｽ髴難ｽ｣闔ｨ諛ｷ・ｯ繝ｻ・ｹ譎｢・ｽ・ｻ驛｢譎｢・ｽ・ｻ
fn subst_type(t: &str, type_params: &[String], arg: &str) -> String {
    // Split the concrete argument list at the top level (respecting nested
    // parentheses) so `arg` like `int,int` or `List(int),int` maps positionally
    // onto the type parameters.
    let concrete_args = split_top_args(arg);

    // Find the outermost `(...)` argument list of `t` (if any) and substitute
    // each positional slot by name. A naive global `.replace` would corrupt
    // types such as `HashMap(K,V)` -> `HashMap(int,int,int,int)`.
    if let Some(open) = t.find('(') {
        if let Some(close) = t.rfind(')') {
            if open < close {
                let name = &t[..open];
                let inner = &t[open + 1..close];
                let slots = split_top_args(inner);
                let mut out_slots: Vec<String> = Vec::new();
                for (i, slot) in slots.iter().enumerate() {
                    let slot_trim = slot.trim();
                    let mut replaced = slot_trim.to_string();
                    if let Some(tp) = type_params.get(i) {
                        if slot_trim == tp.as_str() {
                            if let Some(c) = concrete_args.get(i) {
                                replaced = c.clone();
                            }
                        }
                    }
                    out_slots.push(replaced);
                }
                return format!("{}({})", name, out_slots.join(", "));
            }
        }
    }
    // No parenthesised args: still honour a direct whole-string parameter match.
    if type_params.iter().any(|tp| tp.as_str() == t) {
        if let Some(idx) = type_params.iter().position(|tp| tp.as_str() == t) {
            if let Some(c) = concrete_args.get(idx) {
                return c.clone();
            }
        }
    }
    t.to_string()
}

/// Split a comma-separated argument list at the top level, ignoring commas
/// nested inside parentheses. `split_top_args("int,int")` -> `["int","int"]`.
fn split_top_args(s: &str) -> Vec<String> {
    let mut args: Vec<String> = Vec::new();
    let mut depth: i32 = 0;
    let mut cur = String::new();
    for c in s.chars() {
        match c {
            '(' => {
                depth += 1;
                cur.push(c);
            }
            ')' => {
                depth -= 1;
                cur.push(c);
            }
            ',' if depth == 0 => {
                args.push(cur.trim().to_string());
                cur.clear();
            }
            _ => cur.push(c),
        }
    }
    if !cur.trim().is_empty() {
        args.push(cur.trim().to_string());
    }
    args
}

/// Build an `Expr` for a dotted path such as `a.b.c` (used to re-interpret
/// `obj.field.method(...)` calls that the parser emitted as a single Call).
fn expr_from_path(path: &str) -> Expr {
    let mut parts: Vec<&str> = path.split('.').collect();
    let mut expr = Expr::Ident(parts.remove(0).to_string());
    for p in parts {
        expr = Expr::FieldAccess {
            object: Box::new(expr),
            field: p.to_string(),
        };
    }
    expr
}

/// Dispatch a method call on an already-evaluated object value. Shared between
/// the `Expr::MethodCall` evaluator and the `obj.field.method()` fallback in the
/// `Expr::Call` evaluator.
fn dispatch_method(
    obj: Value,
    method: &str,
    arg_vals: Vec<Value>,
    env: &HashMap<String, Value>,
    defs: &Defs,
) -> Result<Value, String> {
    match obj {
        Value::StringBuilder(s) => match method {
            "build" => Ok(Value::String(s)),
            other => Err(format!("Unknown StringBuilder method: {}", other)),
        },
        Value::Array(arr) => eval_list_method_ext(&arr, method, &arg_vals),
        Value::String(s) => eval_string_method(&s, method, &arg_vals),
        Value::Float(f) => eval_float_method(f, method, &arg_vals),
        Value::Struct { name, fields } => {
            eval_struct_method_or_call(&name, &fields, method, arg_vals, defs)
        }
        other => Err(format!("Type {:?} has no method '{}'", other, method)),
    }
}

/// Try the method-form dispatch for library structs first; if the struct has no
/// matching library method, fall back to registered struct methods via
/// `call_method` (so user-defined structs keep working).
fn eval_struct_method_or_call(
    name: &str,
    fields: &Vec<(String, Value)>,
    method: &str,
    arg_vals: Vec<Value>,
    defs: &Defs,
) -> Result<Value, String> {
    match eval_struct_method(name, fields, method, arg_vals.clone(), defs) {
        Ok(v) => Ok(v),
        Err(e) if e.contains("Unknown method") => call_method(name, fields, method, arg_vals, defs),
        Err(e) => Err(e),
    }
}

