/// Encode a single concrete type argument for embedding in a mangled function
/// name. Alphanumeric bytes pass through unchanged (keeping flat names like
/// `option.unwrap.int` stable); every other byte becomes `_XX` (uppercase hex),
/// so nested generic states (`Option(int)`, `Result(int, str)`,
/// `collections.HashMap`) map to valid LLVM identifier segments and can never
/// be confused with the `.` argument separator.
fn mangle_type_arg(t: &str) -> String {
    let mut out = String::with_capacity(t.len());
    for b in t.bytes() {
        if b.is_ascii_alphanumeric() {
            out.push(b as char);
        } else {
            out.push_str(&format!("_{:02X}", b));
        }
    }
    out
}

/// Centralized, deterministic generic-symbol mangling. Produces a
/// collision-free internal name for a function/base plus its concrete
/// type arguments (e.g. "max" + ["i64"] -> "max.i64"). Alphanumeric
/// argument bytes pass through untouched, so already-flat names like
/// "option.unwrap.int" stay stable across builds; nested generic states
/// (e.g. "Option_28int_29") and special characters are hex-encoded by
/// `mangle_type_arg` so the result is a valid LLVM identifier segment.
/// This is the single source of truth used by both the interpreter
/// (`Phase 6` monomorphization) and the LLVM backend.
fn mangled_name(base: &str, type_args: &[&str]) -> String {
    let mut s = base.to_string();
    for a in type_args {
        s.push('.');
        s.push_str(&mangle_type_arg(a));
    }
    s
}

/// Parse "func(Type1, Type2)" into ("func", ["Type1", "Type2"])
fn parse_generic_call_name(func: &str) -> Option<(&str, Vec<&str>)> {
    if let Some(paren_idx) = func.find('(') {
        let base = &func[..paren_idx];
        let inner = &func[paren_idx + 1..func.len() - 1];
        let args: Vec<&str> = if inner.is_empty() {
            Vec::new()
        } else {
            inner.split(", ").collect()
        };
        Some((base, args))
    } else {
        None
    }
}

#[cfg(test)]
mod mangle_tests {
    use super::*;

    /// mangle_type_arg must be injective: distinct concrete types must never
    /// map to the same encoded segment, so mangled names can never collide.
    #[test]
    fn mangle_type_arg_is_injective() {
        let cases = [
            ("i64", "i64"),
            ("string", "string"),
            ("bool", "bool"),
            ("double", "double"),
            ("Option(int)", "Option_28int_29"),
            ("Result(int, string)", "Result_28int_2C_20string_29"),
            ("collections.HashMap", "collections_2EHashMap"),
            ("Option(Result(double, bool))", "Option_28Result_28double_2C_20bool_29_29"),
        ];
        for (src, want) in cases {
            assert_eq!(mangle_type_arg(src), want, "encode {}", src);
        }
        let mut seen = std::collections::HashSet::new();
        for (src, _) in cases {
            let enc = mangle_type_arg(src);
            assert!(
                seen.insert(enc.clone()),
                "collision detected for {} -> {}",
                src,
                enc
            );
        }
    }

    /// Two generic instantiations with the same base name but different
    /// concrete type arguments must produce distinct internal symbols.
    #[test]
    fn same_base_different_args_are_distinct() {
        let a = mangled_name("max", &["int"]);
        let b = mangled_name("max", &["float"]);
        assert_eq!(a, "max.int");
        assert_eq!(b, "max.float");
        assert_ne!(a, b, "max<int> and max<float> must not collide");
    }

    /// Nested generic types must each encode to a unique, dot-free LLVM
    /// identifier segment (no parentheses/commas leak into symbols).
    #[test]
    fn nested_generics_encode_uniquely() {
        let flat = mangled_name("option.unwrap", &["Option(int)"]);
        let nested = mangled_name("option.unwrap", &["Option(Result(int, string))"]);
        let deep = mangled_name("option.unwrap", &["Option(Option(int))"]);
        assert_eq!(flat, "option.unwrap.Option_28int_29");
        assert_eq!(
            nested,
            "option.unwrap.Option_28Result_28int_2C_20string_29_29"
        );
        assert_eq!(deep, "option.unwrap.Option_28Option_28int_29_29");
        assert_ne!(flat, nested);
        assert_ne!(nested, deep);
        assert_ne!(flat, deep);
        for s in [&flat, &nested, &deep] {
            assert!(
                !s.contains('(') && !s.contains(')') && !s.contains(','),
                "must be a valid LLVM identifier: {}",
                s
            );
        }
    }

    /// Different arg counts on the same base must differ (the dot separator
    /// is unambiguous because encoded args never contain a literal dot).
    #[test]
    fn arg_count_distinguishes() {
        let one = mangled_name("wrap", &["int"]);
        let two = mangled_name("wrap", &["int", "string"]);
        let three = mangled_name("wrap", &["int", "string", "bool"]);
        assert_ne!(one, two);
        assert_ne!(two, three);
        assert_ne!(one, three);
    }

    /// Mangling must be deterministic and stable across repeated calls and
    /// builds (pure string encoding, no hashing or map-ordering involved).
    #[test]
    fn mangling_is_deterministic() {
        for _ in 0..100 {
            assert_eq!(
                mangled_name("option.unwrap", &["Option(Int)"]),
                "option.unwrap.Option_28Int_29"
            );
            assert_eq!(
                mangle_type_arg("Result(int, string)"),
                "Result_28int_2C_20string_29"
            );
        }
    }
}

fn monomorphize_type_str(t: &str, type_params: &[String], type_args: &[&str]) -> String {
    let mut result = t.to_string();
    for (i, tp) in type_params.iter().enumerate() {
        if i < type_args.len() {
            result = result.replace(tp.as_str(), type_args[i]);
        }
    }
    result
}

fn monomorphize_function(fdef: &FunctionDef, type_params: &[String], type_args: &[&str]) -> FunctionDef {
    let params: Vec<(String, String)> = fdef.params.iter()
        .map(|(n, t)| (n.clone(), monomorphize_type_str(t, type_params, type_args)))
        .collect();
    let return_type = fdef.return_type.as_ref()
        .map(|rt| monomorphize_type_str(rt, type_params, type_args));
    FunctionDef {
        type_params: Vec::new(),
        constraints: Vec::new(),
        params,
        return_type,
        body: fdef.body.clone(),
        is_async: fdef.is_async,
    }
}

/// Infer concrete type arguments from call arguments for a generic function.
fn infer_generic_args(
    func_name: &str,
    call_args: &[Expr],
    env: &HashMap<String, Type>,
    defs: &Defs,
    expected: Option<&Type>,
) -> Result<Vec<String>, String> {
    let fdef = defs.functions.get(func_name).ok_or_else(|| {
        format!("function '{}' not found", func_name)
    })?;
    if fdef.type_params.is_empty() {
        return Err(format!("'{}' is not a generic function", func_name));
    }

    let mut type_map: HashMap<String, String> = HashMap::new();
    for (arg, (_, ptype_str)) in call_args.iter().zip(fdef.params.iter()) {
        let arg_type = infer_type(arg, env, defs, &HashMap::new())?;
        let arg_str = type_to_string(&arg_type);
        let ptype = type_from_str(ptype_str, defs);
        match &ptype {
            Type::Var(tv) => {
                if let Some(existing) = type_map.get(tv) {
                    // `unknown` is a wildcard: an argument whose type could not
                    // be inferred yet must not veto a later concrete binding.
                    if existing != &arg_str && existing != "unknown" && arg_str != "unknown" {
                        return Err(format!(
                            "Type mismatch for type parameter '{}': inferred '{}' and '{}' (func={})",
                            tv, existing, arg_str, func_name
                        ));
                    }
                }
                type_map.insert(tv.clone(), arg_str);
            }
            _ => {
                // For non-Var param types like List(T), infer from inner types
                collect_var_bindings(&arg_type, &ptype, &mut type_map, defs)?;
            }
        }
    }

    let mut result = Vec::new();
    'outer: for tp in &fdef.type_params {
        match type_map.get(tp) {
            Some(s) => result.push(s.clone()),
            None => {
                // No call argument pinned this type parameter. Fall back to the
                // expected return type (e.g. the declared type of the assignment
                // target, `let HashMap(int,int): m = make_hash_map()`), which
                // carries the concrete type arguments for zero-arg constructors.
                if let Some(exp) = expected {
                    let mut bindings: HashMap<String, String> = HashMap::new();
                    let ret_ty = type_from_str(&fdef.return_type.clone().unwrap_or_default(), defs);
                    if collect_var_bindings(exp, &ret_ty, &mut bindings, defs).is_ok() {
                        if let Some(s) = bindings.get(tp) {
                            result.push(s.clone());
                            continue;
                        }
                    }
                    // Fallback: return type string may not have embedded generic
                    // args (e.g. "collections.HashMap" instead of the more
                    // precise "collections.HashMap(K,V)").  Try matching by
                    // position through the struct's type parameter names.
                    if let Some(rt_str) = &fdef.return_type {
                        let base = rt_str.split('(').next().unwrap_or(rt_str);
                        if let Some(sd) = defs.structs.get(base) {
                            if !sd.type_params.is_empty() {
                                let exp_str = type_to_string(exp);
                                let exp_args = generic_args_of(&exp_str);
                                if exp_args.len() == sd.type_params.len() {
                                    for (i, stp) in sd.type_params.iter().enumerate() {
                                        if stp == tp {
                                            if let Some(earg) = exp_args.get(i) {
                                                result.push(earg.clone());
                                                continue 'outer;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                return Err(format!(
                    "Cannot infer type parameter '{}' from call arguments in '{}'",
                    tp, func_name
                ));
            }
        }
    }
    Ok(result)
}

/// Collect type variable bindings by matching concrete types against pattern types.
fn collect_var_bindings(
    concrete: &Type,
    pattern: &Type,
    type_map: &mut HashMap<String, String>,
    defs: &Defs,
) -> Result<(), String> {
    // `unknown` on the concrete side is a wildcard: it carries no information
    // yet, so it must not bind or veto a type parameter.
    if matches!(concrete, Type::Unknown) {
        return Ok(());
    }
    match (concrete, pattern) {
        (Type::Var(tv), _) => {
            let s = type_to_string(concrete);
            // Never bind a type variable to its own literal name (this happens
            // when the concrete side is itself an unresolved `Var`); treat it as
            // a wildcard instead.
            if s == tv.as_str() || s == "unknown" {
                return Ok(());
            }
            if let Some(existing) = type_map.get(tv) {
                // `unknown` is a wildcard: a not-yet-inferred type does not
                // conflict with a later concrete binding.
                if existing != &s && existing != "unknown" && s != "unknown" {
                    return Err(format!(
                        "Type mismatch for type parameter '{}': '{}' vs '{}'",
                        tv, existing, s
                    ));
                }
            }
            type_map.insert(tv.clone(), s);
            Ok(())
        }
        // concrete is a concrete type, pattern is a type variable: bind the
        // variable to the concrete type's string. (The previous arm handles the
        // symmetric case where the concrete side is itself a variable.)
        (_, Type::Var(tv)) => {
            let s = type_to_string(concrete);
            if s == tv.as_str() || s == "unknown" {
                return Ok(());
            }
            if let Some(existing) = type_map.get(tv) {
                if existing != &s && existing != "unknown" && s != "unknown" {
                    return Err(format!(
                        "Type mismatch for type parameter '{}': '{}' vs '{}'",
                        tv, existing, s
                    ));
                }
            }
            type_map.insert(tv.clone(), s);
            Ok(())
        }
        (Type::List(p_inner), Type::List(c_inner)) => {
            collect_var_bindings(p_inner, c_inner, type_map, defs)
        }
        (Type::Option(p_inner), Type::Option(c_inner)) => {
            collect_var_bindings(p_inner, c_inner, type_map, defs)
        }
        (Type::Array(p_inner), Type::Array(c_inner)) => {
            collect_var_bindings(p_inner, c_inner, type_map, defs)
        }
        // Struct/State: bind their generic arguments (encoded as `(A, B)` in
        // the type name) against each other. The base names must already
        // match for this to be reached as a pattern.
        (Type::Struct(p), Type::Struct(c)) | (Type::State(p), Type::State(c)) => {
            // With the `match (concrete, pattern)` convention below,
            // `p` is the concrete type, `c` is the pattern type.
            let concrete_args = generic_args_of(p);
            let pattern_args = generic_args_of(c);
            if concrete_args.len() != pattern_args.len() {
                return Ok(());
            }
            for (pat, con) in pattern_args.iter().zip(concrete_args.iter()) {
                // `pat` is a pattern argument (may be a `Var`, e.g. `K`),
                // `con` is the matching concrete argument (e.g. `int`).
                match type_from_str(pat, defs) {
                    Type::Var(tv) => {
                        let s = type_to_string(&type_from_str(con, defs));
                        if let Some(existing) = type_map.get(&tv) {
                            if existing != &s && existing != "unknown" && s != "unknown" {
                                return Err(format!(
                                    "Type mismatch for type parameter '{}': '{}' vs '{}'",
                                    tv, existing, s
                                ));
                            }
                        }
                        type_map.insert(tv, s);
                    }
                    _ => {
                        collect_var_bindings(
                            &type_from_str(con, defs),
                            &type_from_str(pat, defs),
                            type_map,
                            defs,
                        )?;
                    }
                }
            }
            Ok(())
        }
        // Mixed representation: `Some(x)` produces `State("Option(int)")` while
        // a generic helper parameter is written `Option(T)`. Unify the two by
        // recursing on the state's concrete inner type.
        (Type::State(name), Type::Option(pat_inner)) | (Type::Option(pat_inner), Type::State(name)) => {
            if struct_base(name) == "Option" {
                let concrete_args = generic_args_of(name);
                if let Some(con_inner) = concrete_args.first() {
                    return collect_var_bindings(
                        &type_from_str(con_inner, defs),
                        pat_inner,
                        type_map,
                        defs,
                    );
                }
            }
            Ok(())
        }
        // Exact match - no bindings
        _ => Ok(()),
    }
}

/// Check that concrete type args satisfy the generic function's constraints.
/// Uses the same constraint system as the type checker.
fn check_generic_constraints(
    fdef: &FunctionDef,
    type_args: &[String],
    defs: &Defs,
) -> Result<(), String> {
    for (tv, iface) in &fdef.constraints {
        for (i, tp) in fdef.type_params.iter().enumerate() {
            if tp == tv && i < type_args.len() {
                let concrete_type = type_from_str(&type_args[i], defs);
                // Use the same logic as check_constraint for struct types
                let ok = match &concrete_type {
                    Type::Struct(sname) => struct_satisfies_interface(defs, sname, iface),
                    Type::Interface(iname, _) => iname == iface,
                    Type::Unknown => true,
                    // Primitives (Int, Float, Bool, String) have built-in operators
                    // and satisfy the corresponding operator interfaces
                    Type::Int | Type::Float | Type::Bool | Type::String => true,
                    _ => false,
                };
                if !ok {
                    return Err(format!(
                        "Type error: {} does not satisfy constraint '{}: {}'",
                        type_to_string(&concrete_type),
                        tv,
                        iface
                    ));
                }
            }
        }
    }
    Ok(())
}

/// Walk expression, collect generic calls and create monomorphized functions.
/// `expected` carries the surrounding assignment's declared type, used to infer
/// type parameters for zero-argument generic constructors.
fn collect_mono_from_expr(
    e: &Expr,
    env: &mut HashMap<String, Type>,
    defs: &Defs,
    mono_fdefs: &mut HashMap<MonoKey, FunctionDef>,
    call_updates: &mut HashMap<String, String>,
    worklist: &mut Vec<String>,
    expected: Option<&Type>,
) -> Result<(), String> {
    match e {
        Expr::Call { func, args } => {
            let base_name;
            let explicit_type_args: Option<Vec<String>>;

            // Check if func has explicit type args like "max(i64)"
            if let Some((base, type_strs)) = parse_generic_call_name(func) {
                base_name = base.to_string();
                explicit_type_args = Some(type_strs.iter().map(|s| s.to_string()).collect());
            } else {
                base_name = func.clone();
                explicit_type_args = None;
            }

            // Check if the base function is a generic template
            let base_name = if defs.functions.contains_key(&base_name) {
                base_name
            } else {
                resolve_pkg_name(defs, &base_name).unwrap_or(base_name)
            };
            if let Some(fdef) = defs.functions.get(&base_name) {
                if !fdef.type_params.is_empty() {
                    // Infer or use explicit type args
                    let type_args: Vec<String> = if let Some(ref explicit) = explicit_type_args {
                        explicit.clone()
                    } else {
                        infer_generic_args(&base_name, args, env, defs, expected)?
                    };

                    // Check constraints
                    check_generic_constraints(fdef, &type_args, defs)?;

                    // Create mangled name
                    let type_arg_refs: Vec<&str> = type_args.iter().map(|s| s.as_str()).collect();
                    let mangled = mangled_name(&base_name, &type_arg_refs);

                    // Only create monomorphized function if not already created.
                    // Keyed by `MonoKey` so the same (function, type-args)
                    // instantiation is never processed twice.
                    let key = MonoKey {
                        function: intern(&base_name),
                        types: type_args.clone(),
                        mangled: mangled.clone(),
                    };
                    if !mono_fdefs.contains_key(&key) {
                        let type_param_strs: Vec<&str> = type_args.iter().map(|s| s.as_str()).collect();
                        let mono = monomorphize_function(fdef, &fdef.type_params, &type_param_strs);
                        mono_fdefs.insert(key, mono);
                        worklist.push(mangled.clone());
                    }

                    // Record the call update (only if name changed)
                    if func != &mangled {
                        call_updates.insert(func.clone(), mangled);
                    }
                }
            }

            // Walk sub-expressions for nested generic calls. Call arguments are
            // evaluated in the caller's scope and never introduce new bindings
            // here, so we reborrow `env` directly instead of cloning it per
            // argument (was O(args * env_size) allocations).
            for a in args {
                collect_mono_from_expr(a, env, defs, mono_fdefs, call_updates, worklist, None)?;
            }
        }
        Expr::BinOp { left, right, .. } => {
            collect_mono_from_expr(left, env, defs, mono_fdefs, call_updates, worklist, None)?;
            collect_mono_from_expr(right, env, defs, mono_fdefs, call_updates, worklist, None)?;
        }
        Expr::UnOp { operand, .. } => {
            collect_mono_from_expr(operand, env, defs, mono_fdefs, call_updates, worklist, None)?;
        }
        Expr::MethodCall { object, args, .. } => {
            collect_mono_from_expr(object, env, defs, mono_fdefs, call_updates, worklist, None)?;
            for a in args {
                collect_mono_from_expr(a, env, defs, mono_fdefs, call_updates, worklist, None)?;
            }
        }
        Expr::FieldAccess { object, .. } => {
            collect_mono_from_expr(object, env, defs, mono_fdefs, call_updates, worklist, None)?;
        }
        Expr::Array(items) => {
            for it in items {
                collect_mono_from_expr(it, env, defs, mono_fdefs, call_updates, worklist, None)?;
            }
        }
        Expr::Range { start, end } => {
            collect_mono_from_expr(start, env, defs, mono_fdefs, call_updates, worklist, None)?;
            collect_mono_from_expr(end, env, defs, mono_fdefs, call_updates, worklist, None)?;
        }
        Expr::Index { target, index } => {
            collect_mono_from_expr(target, env, defs, mono_fdefs, call_updates, worklist, None)?;
            collect_mono_from_expr(index, env, defs, mono_fdefs, call_updates, worklist, None)?;
        }
        Expr::Slice { target, start, end } => {
            collect_mono_from_expr(target, env, defs, mono_fdefs, call_updates, worklist, None)?;
            if let Some(s) = start {
                collect_mono_from_expr(s, env, defs, mono_fdefs, call_updates, worklist, None)?;
            }
            if let Some(e) = end {
                collect_mono_from_expr(e, env, defs, mono_fdefs, call_updates, worklist, None)?;
            }
        }
        Expr::Await(inner) => {
            collect_mono_from_expr(inner, env, defs, mono_fdefs, call_updates, worklist, None)?;
        }
        _ => {}
    }
    Ok(())
}

/// Walk statements to find generic calls, maintaining env for type inference.
fn collect_mono_from_stmts(
    stmts: &[Stmt],
    env: &mut HashMap<String, Type>,
    defs: &Defs,
    mono_fdefs: &mut HashMap<MonoKey, FunctionDef>,
    call_updates: &mut HashMap<String, String>,
    worklist: &mut Vec<String>,
) -> Result<(), String> {
    for s in stmts {
        match s {
            Stmt::Let { name, value, type_hint, .. } => {
                // Infer type and update env before walking the value
                if let Ok(t) = infer_type(value, env, defs, &HashMap::new()) {
                    env.insert(name.clone(), t);
                }
                // The declared type (e.g. `HashMap(int,int)`) lets us infer type
                // parameters for zero-arg generic constructors like `make_hash_map()`,
                // and is authoritative for the binding: store it directly so chained
                // calls see the concrete element types rather than unsubstituted `Var`s.
                let expected = type_hint.as_ref().map(|h| type_from_str(h, defs));
                if let Some(exp) = &expected {
                    env.insert(name.clone(), exp.clone());
                }
                let exp_ref = expected.as_ref();
                collect_mono_from_expr(value, env, defs, mono_fdefs, call_updates, worklist, exp_ref)?;
            }
            Stmt::Return { explicit_type: _, value } => {
                if let Some(e) = value {
                    collect_mono_from_expr(e, env, defs, mono_fdefs, call_updates, worklist, None)?;
                }
            }
            Stmt::Expr(e) => {
                collect_mono_from_expr(e, env, defs, mono_fdefs, call_updates, worklist, None)?;
            }
            Stmt::Assign { name, value } => {
                if let Ok(t) = infer_type(value, env, defs, &HashMap::new()) {
                    env.insert(name.clone(), t);
                }
                collect_mono_from_expr(value, env, defs, mono_fdefs, call_updates, worklist, None)?;
            }
            Stmt::If { cond, then_branch, else_branch } => {
                collect_mono_from_expr(cond, env, defs, mono_fdefs, call_updates, worklist, None)?;
                let mut then_env = env.clone();
                collect_mono_from_stmts(then_branch, &mut then_env, defs, mono_fdefs, call_updates, worklist)?;
                if let Some(eb) = else_branch {
                    let mut else_env = env.clone();
                    collect_mono_from_stmts(eb, &mut else_env, defs, mono_fdefs, call_updates, worklist)?;
                }
            }
            Stmt::While { cond, body } => {
                collect_mono_from_expr(cond, env, defs, mono_fdefs, call_updates, worklist, None)?;
                collect_mono_from_stmts(body, env, defs, mono_fdefs, call_updates, worklist)?;
            }
            Stmt::For { var, iterable, body } => {
                if let Ok(it_ty) = infer_type(iterable, env, defs, &HashMap::new()) {
                    let elem = match &it_ty {
                        Type::List(e) => (**e).clone(),
                        _ => Type::Unknown,
                    };
                    env.insert(var.clone(), elem);
                }
                collect_mono_from_expr(iterable, env, defs, mono_fdefs, call_updates, worklist, None)?;
                collect_mono_from_stmts(body, env, defs, mono_fdefs, call_updates, worklist)?;
            }
            Stmt::Match { expr, arms } => {
                collect_mono_from_expr(expr, env, defs, mono_fdefs, call_updates, worklist, None)?;
                for (_, body) in arms {
                    let mut arm_env = env.clone();
                    collect_mono_from_stmts(body, &mut arm_env, defs, mono_fdefs, call_updates, worklist)?;
                }
            }
            _ => {}
        }
    }
    Ok(())
}

/// Update Expr::Call.func in an expression tree using the call_updates mapping.
fn update_call_in_expr(e: &mut Expr, call_updates: &HashMap<String, String>) {
    match e {
        Expr::Call { func, args } => {
            if let Some(new_name) = call_updates.get(func.as_str()) {
                *func = new_name.clone();
            }
            for a in args {
                update_call_in_expr(a, call_updates);
            }
        }
        Expr::BinOp { left, right, .. } => {
            update_call_in_expr(left, call_updates);
            update_call_in_expr(right, call_updates);
        }
        Expr::UnOp { operand, .. } => {
            update_call_in_expr(operand, call_updates);
        }
        Expr::MethodCall { object, args, .. } => {
            update_call_in_expr(object, call_updates);
            for a in args {
                update_call_in_expr(a, call_updates);
            }
        }
        Expr::FieldAccess { object, .. } => {
            update_call_in_expr(object, call_updates);
        }
        Expr::Array(items) => {
            for it in items {
                update_call_in_expr(it, call_updates);
            }
        }
        Expr::Range { start, end } => {
            update_call_in_expr(start, call_updates);
            update_call_in_expr(end, call_updates);
        }
        Expr::Await(inner) => {
            update_call_in_expr(inner, call_updates);
        }
        _ => {}
    }
}

/// Update Expr::Call.func in statements using the call_updates mapping.
fn update_call_in_stmts(stmts: &mut [Stmt], call_updates: &HashMap<String, String>) {
    for s in stmts.iter_mut() {
        match s {
            Stmt::Let { value, .. } => update_call_in_expr(value, call_updates),
            Stmt::Return { explicit_type: _, value } => {
                if let Some(e) = value {
                    update_call_in_expr(e, call_updates);
                }
            }
            Stmt::Expr(e) => update_call_in_expr(e, call_updates),
            Stmt::Assign { value, .. } => update_call_in_expr(value, call_updates),
            Stmt::If { cond, then_branch, else_branch } => {
                update_call_in_expr(cond, call_updates);
                update_call_in_stmts(then_branch, call_updates);
                if let Some(eb) = else_branch {
                    update_call_in_stmts(eb, call_updates);
                }
            }
            Stmt::While { cond, body } => {
                update_call_in_expr(cond, call_updates);
                update_call_in_stmts(body, call_updates);
            }
            Stmt::For { iterable, body, .. } => {
                update_call_in_expr(iterable, call_updates);
                update_call_in_stmts(body, call_updates);
            }
            Stmt::Match { expr, arms } => {
                update_call_in_expr(expr, call_updates);
                for (_, body) in arms {
                    update_call_in_stmts(body, call_updates);
                }
            }
            Stmt::Fn { body, .. } => {
                update_call_in_stmts(body, call_updates);
            }
            Stmt::Struct { methods, .. } => {
                update_call_in_stmts(methods, call_updates);
            }
            _ => {}
        }
    }
}

/// Main monomorphization pass: discovers generic calls, creates concrete instances,
/// updates call names, and adds monomorphized functions to defs.
/// Runs after type checking, before memory analysis and codegen.
fn monomorphize_all(defs: &mut Defs, stmts: &mut [Stmt]) -> Result<(), String> {
    let mut mono_fdefs: HashMap<MonoKey, FunctionDef> = HashMap::new();
    let mut call_updates: HashMap<String, String> = HashMap::new();

    let mut worklist: Vec<String> = defs.functions.keys().cloned().collect();
    let mut processed: std::collections::HashSet<String> = std::collections::HashSet::new();

    // Also scan top-level statements for generic calls
    let mut env: HashMap<String, Type> = HashMap::new();
    collect_mono_from_stmts(
        stmts,
        &mut env,
        defs,
        &mut mono_fdefs,
        &mut call_updates,
        &mut worklist,
    )?;

    // Iterative worklist: process functions and their newly created monomorphized clones
    while let Some(func_name) = worklist.pop() {
        if processed.contains(&func_name) {
            continue;
        }
        processed.insert(func_name.clone());

        let fdef = match defs.functions.get(&func_name) {
            Some(f) => f.clone(),
            None => continue,
        };

        // Build env from function parameters for type inference
        let mut env: HashMap<String, Type> = HashMap::new();
        for (pname, ptype) in &fdef.params {
            env.insert(pname.clone(), type_from_str(ptype, defs));
        }

        collect_mono_from_stmts(
            &fdef.body,
            &mut env,
            defs,
            &mut mono_fdefs,
            &mut call_updates,
            &mut worklist,
        )?;
    }

    // Add monomorphized functions to defs
    for (key, fdef) in &mono_fdefs {
        let mangled = &key.mangled;
        if !defs.functions.contains_key(mangled) {
            defs.functions.insert(mangled.clone(), fdef.clone());
        }
    }

    // Update Expr::Call.func in all function bodies to use mangled names
    for (_name, fdef) in defs.functions.iter_mut() {
        update_call_in_stmts(&mut fdef.body, &call_updates);
    }
    // Also update top-level statements (after scanning so env is fresh)
    update_call_in_stmts(stmts, &call_updates);

    Ok(())
}

