/// Render the memory-analysis result as a human-readable report. Emitted only
/// under `--verbose`; goes to stderr so it never contaminates program stdout.
fn report_memory(memory: &HashMap<String, MemoryPlace>) {
    eprintln!("=== Memory ===");
    let mut entries: Vec<(&String, &MemoryPlace)> = memory.iter().collect();
    entries.sort_by(|a, b| a.0.cmp(b.0));
    for (name, place) in entries {
        let p = match place {
            MemoryPlace::Stack => "stack",
            MemoryPlace::Heap => "heap",
        };
        eprintln!("  {} -> {}", name, p);
    }
    eprintln!();
}

