fn eval_float_method(v: f64, method: &str, args: &[Value]) -> Result<Value, String> {
    match method {
        "abs" => {
            if !args.is_empty() {
                return Err("abs() takes no arguments".to_string());
            }
            Ok(Value::Float(v.abs()))
        }
        "sqrt" => {
            if !args.is_empty() {
                return Err("sqrt() takes no arguments".to_string());
            }
            Ok(Value::Float(v.sqrt()))
        }
        "floor" => {
            if !args.is_empty() {
                return Err("floor() takes no arguments".to_string());
            }
            Ok(Value::Float(v.floor()))
        }
        "ceil" => {
            if !args.is_empty() {
                return Err("ceil() takes no arguments".to_string());
            }
            Ok(Value::Float(v.ceil()))
        }
        "round" => {
            if !args.is_empty() {
                return Err("round() takes no arguments".to_string());
            }
            Ok(Value::Float(v.round()))
        }
        other => Err(format!("Unknown Float method: {}", other)),
    }
}

